-- Candidate regression suite. Run only after loading the draft SQL on a disposable schema.
UPDATE public.turmas SET tempo_lectivo_minutos=45 WHERE escola_id='10000000-0000-0000-0000-000000000001';
DO $tests$
DECLARE s uuid:='10000000-0000-0000-0000-000000000001';
 p uuid:='40000000-0000-0000-0000-000000000001';
 t uuid:='b0000000-0000-0000-0000-000000000001';
 m uuid:='a0000000-0000-0000-0000-000000000005'; n integer;
BEGIN
 IF NOT public.teacher_workload_exceeds(s,t,17,765,4,20,NULL) THEN RAISE EXCEPTION 'LEGACY_LIMIT_CHANGED'; END IF;
 IF public.teacher_workload_exceeds(s,t,17,765,4,20,1200) THEN RAISE EXCEPTION 'CLOCK_HOURS_FALSE_POSITIVE'; END IF;
 IF NOT public.teacher_workload_exceeds(s,t,26,1170,1,20,1200) THEN RAISE EXCEPTION 'CLOCK_HOURS_OVERFLOW'; END IF;
 IF public.teacher_workload_exceeds(s,t,25,1125,1,20,1200) THEN RAISE EXCEPTION 'CLOCK_HOURS_BOUNDARY'; END IF;
 PERFORM public.configure_teacher_workload_atomic(s,p,'minutos',1200,1200);
 SELECT public.assign_teacher_regime_atomic(s,t,'monodocencia',p,NULL) INTO n;
 IF n<>1 THEN RAISE EXCEPTION 'MONODOCENCIA_COUNT'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.turmas WHERE id=t AND professor_titular_id=p AND regime_docencia='monodocencia') THEN RAISE EXCEPTION 'MISSING_TITULAR'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.turma_disciplinas WHERE turma_id=t AND curso_matriz_id=m AND professor_id=p) THEN RAISE EXCEPTION 'MISSING_LINK'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.get_teacher_workload_config(s,p) w WHERE w.unidade='minutos' AND w.limite=1200 AND w.tempos_atribuidos=2 AND w.minutos_atribuidos=90) THEN RAISE EXCEPTION 'LOAD_PROJECTION_MISMATCH'; END IF;
 -- A conflicting owner must roll back the attempted regime.
 BEGIN
   PERFORM public.assign_teacher_regime_atomic(s,t,'monodocencia','40000000-0000-0000-0000-000000000002',NULL);
   RAISE EXCEPTION 'EXPECTED_CONFLICT';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_REGIME_TITULAR_CONFLICT%' THEN RAISE; END IF; END;
 IF NOT EXISTS (SELECT 1 FROM public.turmas WHERE id=t AND professor_titular_id=p) THEN RAISE EXCEPTION 'REGIME_PARTIAL_WRITE'; END IF;
 -- Lowering an assigned 90-minute load to 89 is rejected.
 BEGIN
  PERFORM public.configure_teacher_workload_atomic(s,p,'minutos',89,1200);
  RAISE EXCEPTION 'EXPECTED_LOW_LIMIT_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_LOAD_BELOW_ASSIGNED%' THEN RAISE; END IF; END;
 -- A subset assigned to the same teacher cannot downgrade mono.
 PERFORM public.assign_teacher_regime_atomic(s,t,'misto',p,ARRAY[m]);
 IF NOT EXISTS (SELECT 1 FROM public.turmas WHERE id=t AND regime_docencia='monodocencia' AND professor_titular_id=p) THEN RAISE EXCEPTION 'MONO_DOWNGRADE'; END IF;
 -- Direct legacy assignment to a different professor is forbidden.
 BEGIN
  UPDATE public.turma_disciplinas SET professor_id='40000000-0000-0000-0000-000000000002' WHERE turma_id=t AND curso_matriz_id=m;
  RAISE EXCEPTION 'EXPECTED_DIRECT_MONO_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_MONODOCENCIA_TITULAR_MISMATCH%' THEN RAISE; END IF; END;
 -- Direct assignment cannot circumvent the minute limit on a different turma.
 PERFORM public.configure_teacher_workload_atomic(s,p,'minutos',90,1200);
 BEGIN
  UPDATE public.turma_disciplinas SET professor_id=p
   WHERE turma_id='b0000000-0000-0000-0000-000000000002';
  RAISE EXCEPTION 'EXPECTED_LEGACY_WORKLOAD_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'ASSIGN_PROF_CARGA_EXCEEDED%' THEN RAISE; END IF; END;
 BEGIN
  INSERT INTO public.turma_disciplinas_professores(escola_id,turma_id,disciplina_id,professor_id)
  VALUES(s,'b0000000-0000-0000-0000-000000000002','80000000-0000-0000-0000-000000000001',p);
  RAISE EXCEPTION 'EXPECTED_SHARED_WORKLOAD_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'ASSIGN_PROF_CARGA_EXCEEDED%' THEN RAISE; END IF; END;
 -- A new published subject can be assigned to a specialist without silently
 -- changing the titular; the exact same assignment motor is reused.
 INSERT INTO public.disciplinas_catalogo(id,escola_id,nome) VALUES ('80000000-0000-0000-0000-000000000009',s,'Música');
 INSERT INTO public.curso_matriz(id,escola_id,curso_id,classe_id,disciplina_id,curso_curriculo_id,carga_horaria_semanal,ativo)
 VALUES ('a0000000-0000-0000-0000-000000000019',s,'60000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000005','80000000-0000-0000-0000-000000000009','90000000-0000-0000-0000-000000000005',2,true);
 INSERT INTO public.turma_disciplinas(id,escola_id,turma_id,curso_matriz_id,carga_horaria_semanal)
 VALUES ('c0000000-0000-0000-0000-000000000019',s,t,'a0000000-0000-0000-0000-000000000019',2);
 PERFORM public.assign_teacher_regime_atomic(s,t,'misto','40000000-0000-0000-0000-000000000002',ARRAY['a0000000-0000-0000-0000-000000000019'::uuid]);
 IF NOT EXISTS (SELECT 1 FROM public.turmas WHERE id=t AND professor_titular_id=p AND regime_docencia='misto') THEN RAISE EXCEPTION 'MIXED_TITULAR_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.turma_disciplinas WHERE turma_id=t AND curso_matriz_id='a0000000-0000-0000-0000-000000000019' AND professor_id='40000000-0000-0000-0000-000000000002') THEN RAISE EXCEPTION 'MIXED_SPECIALIST_MISSING'; END IF;
 -- A confirmed single-subject swap must not remove the last titular link.
 BEGIN
  PERFORM public.trocar_professor_turma_disciplina_atomic(s,t,m,p,'40000000-0000-0000-0000-000000000002');
  RAISE EXCEPTION 'EXPECTED_LAST_TITULAR_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_REGIME_TITULAR_LAST_SUBJECT%' THEN RAISE; END IF; END;
 -- A titular change is explicit, atomic, CAS-protected and leaves specialist links intact.
 SELECT public.replace_teacher_titular_atomic(s,t,p,'40000000-0000-0000-0000-000000000002') INTO n;
 IF n<>1 OR NOT EXISTS(SELECT 1 FROM public.turmas WHERE id=t AND professor_titular_id='40000000-0000-0000-0000-000000000002') THEN RAISE EXCEPTION 'TITULAR_REPLACEMENT_FAILED'; END IF;
 IF (SELECT count(*) FROM public.turma_disciplinas WHERE turma_id=t AND professor_id='40000000-0000-0000-0000-000000000002')<>2 THEN RAISE EXCEPTION 'TITULAR_REPLACEMENT_LINKS'; END IF;
 BEGIN
  PERFORM public.replace_teacher_titular_atomic(s,t,p,'40000000-0000-0000-0000-000000000002');
  RAISE EXCEPTION 'EXPECTED_STALE_TITULAR_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_REGIME_TITULAR_CONFLICT%' THEN RAISE; END IF; END;
 -- Missing duration is fail-closed for minute limits, not legacy periods.
 UPDATE public.turmas SET tempo_lectivo_minutos=NULL WHERE id=t;
 BEGIN
  PERFORM public.teacher_workload_exceeds(s,t,0,0,1,20,1200);
  RAISE EXCEPTION 'EXPECTED_DURATION_REJECTION';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_LOAD_DURATION_UNCONFIGURED%' THEN RAISE; END IF; END;
 IF public.teacher_workload_exceeds(s,t,0,0,1,20,NULL) THEN RAISE EXCEPTION 'LEGACY_DURATION_REQUIRED'; END IF;
END $tests$;
SELECT pg_catalog.set_config('app.test_uid','20000000-0000-0000-0000-000000000002',true);
DO $tests$ BEGIN
 BEGIN
  PERFORM public.configure_teacher_workload_atomic('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','minutos',1200,1200);
  RAISE EXCEPTION 'EXPECTED_FORBIDDEN';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_LOAD_FORBIDDEN%' THEN RAISE; END IF; END;
END $tests$;
ROLLBACK;
